#include "robot_capabilities.h"
robot_capability_error_t robot_velocity_set_rpm(robot_endpoint_t *e,int16_t rpm){if(!e)return ROBOT_CAP_INVALID_ARGUMENT;if(!e->available)return ROBOT_CAP_UNAVAILABLE;if(!(e->capabilities&ROBOT_CAPABILITY_VELOCITY_RPM)||!e->velocity_rpm||!e->velocity_rpm->ops||!e->velocity_rpm->ops->set_velocity_rpm)return ROBOT_CAP_UNSUPPORTED;if(!e->velocity_rpm->context)return ROBOT_CAP_INVALID_ARGUMENT;if(rpm<e->velocity_rpm->min_rpm||rpm>e->velocity_rpm->max_rpm)return ROBOT_CAP_OUT_OF_RANGE;return e->velocity_rpm->ops->set_velocity_rpm(e->velocity_rpm,rpm);}
robot_capability_error_t robot_endpoint_stop(robot_endpoint_t *e){if(!e)return ROBOT_CAP_INVALID_ARGUMENT;if(!e->available)return ROBOT_CAP_UNAVAILABLE;if(!(e->capabilities&ROBOT_CAPABILITY_STOPPABLE)||!e->stoppable||!e->stoppable->ops||!e->stoppable->ops->stop)return ROBOT_CAP_UNSUPPORTED;if(!e->stoppable->context)return ROBOT_CAP_INVALID_ARGUMENT;return e->stoppable->ops->stop(e->stoppable);}
void robot_endpoint_registry_init(robot_endpoint_registry_t*r){if(r){r->count=0;for(size_t i=0;i<ROBOT_ENDPOINT_REGISTRY_MAX;i++)r->items[i]=0;}}
bool robot_endpoint_has_capability(const robot_endpoint_t*e,uint32_t c){return e&&(e->capabilities&c)==c;}
robot_endpoint_t*robot_endpoint_registry_find(const robot_endpoint_registry_t*r,robot_endpoint_id_t id){if(!r)return 0;for(size_t i=0;i<r->count;i++)if(r->items[i]->id==id)return r->items[i];return 0;}
robot_registry_error_t robot_endpoint_registry_add(robot_endpoint_registry_t*r,robot_endpoint_t*e){if(!r||!e||!e->name)return ROBOT_REGISTRY_INVALID_ARGUMENT;if(robot_endpoint_registry_find(r,e->id))return ROBOT_REGISTRY_DUPLICATE_ID;if(r->count>=ROBOT_ENDPOINT_REGISTRY_MAX)return ROBOT_REGISTRY_FULL;if(((e->capabilities&ROBOT_CAPABILITY_VELOCITY_RPM)&&!e->velocity_rpm)||((e->capabilities&ROBOT_CAPABILITY_STOPPABLE)&&!e->stoppable)||(!(e->capabilities&ROBOT_CAPABILITY_VELOCITY_RPM)&&e->velocity_rpm)||(!(e->capabilities&ROBOT_CAPABILITY_STOPPABLE)&&e->stoppable))return ROBOT_REGISTRY_CAPABILITY_MISMATCH;r->items[r->count++]=e;return ROBOT_REGISTRY_OK;}
const robot_endpoint_t*robot_endpoint_registry_at(const robot_endpoint_registry_t*r,size_t i){return r&&i<r->count?r->items[i]:0;}
